const RING = 100;
function hashPos(s){let x=2166136261>>>0;for(let i=0;i<s.length;i++){x^=s.charCodeAt(i);x=Math.imul(x,16777619)>>>0;}return x % RING;}
// nodes sorted ascending by pos
const nodes = [ {id:'A',pos:10}, {id:'B',pos:40}, {id:'C',pos:70} ];
function nodeFor(key) {
  const h = hashPos(key);
  for (const n of nodes) {
    if (n.pos >= h) return n.id;
  }
  return null; // BUG: key past the last node should wrap to the first node
}

