function ownerForPos(h){ for(const n of nodes){ if(n.pos>=h) return n.id; } return nodes[0].id; }
let ok = true;
let sawWrap = false;
for (let i = 0; i < 4000; i++) {
  const k = 'k:' + i;
  const h = hashPos(k);
  if (h > 70) sawWrap = true; // these must wrap to A
  const got = nodeFor(k);
  if (got === null) { ok = false; break; }
  if (got !== ownerForPos(h)) { ok = false; break; }
}
ok = ok && sawWrap;
console.log(ok ? 'PASS' : 'FAIL wrap keys mis-assigned or null');

