async function rebalance(range, oldShard, newShard) {
  // 1. copy the range to the new shard
  const rows = await oldShard.read(range);
  await newShard.bulkInsert(rows);          // full-speed, no throttle

  // 2. point the router at the new shard
  router.setOwner(range, newShard);

  // 3. delete from the old shard
  await oldShard.delete(range);
}
